<?php
$path=sys_get_temp_dir().'/cnr-admin-'.bin2hex(random_bytes(5)).'.sqlite';putenv('APP_DSN=sqlite:'.$path);require __DIR__.'/../src/bootstrap.php';require __DIR__.'/../src/actions.php';db()->exec(file_get_contents(__DIR__.'/../src/schema.sql'));$n=0;
function ck($v,$m){global $n;if(!$v)throw new RuntimeException($m);$n++;}
function deny($f){db()->beginTransaction();try{$f();}catch(RuntimeException $e){db()->rollBack();ck(true,'denied');return;}db()->rollBack();throw new RuntimeException('Not denied');}
foreach(['faculty','hod','daa','admin','president']as $role)q('INSERT INTO users(name,email,password,role,department) VALUES(?,?,?,?,?)',[$role,$role==='daa'?'tshotsho.cnr@rub.edu.bt':$role.'@example.test','unused',$role,departments()[0]]);
$u=[];foreach(all('SELECT * FROM users')as $v)$u[$v['role']]=$v;
$p=['module'=>'substitution','department'=>departments()[0],'substitution_required'=>'No','no_substitution_reason'=>'No classes.','travel_start'=>'2026-10-12','travel_end'=>'2026-10-12','purpose_category'=>'Training','place'=>'Thimphu','funding_agency'=>'College','transportation'=>'Pool'];
$id=submitRequest($u['faculty'],$p);$rows=requestNotificationRows($id);$emails=array_column($rows,'recipient');ck(in_array('faculty@example.test',$emails),'applicant queued');ck(in_array('daa.cnr@rub.edu.bt',$emails),'DAA office queued');ck(!in_array('tshotsho.cnr@rub.edu.bt',$emails),'DAA personal excluded');
$other=submitRequest($u['faculty'],$p);deny(fn()=>adminRequestAction($u['hod'],$id,'delete_request','Duplicate'));deny(fn()=>adminRequestAction($u['admin'],$id,'delete_request',''));
db()->beginTransaction();adminRequestAction($u['admin'],$id,'resend_request_notifications');db()->commit();ck(count(array_filter(requestNotificationRows($id),fn($r)=>$r['status']==='superseded'))===count($rows),'old queued superseded');deny(fn()=>adminRequestAction($u['admin'],$id,'resend_request_notifications'));
db()->beginTransaction();adminRequestAction($u['admin'],$id,'delete_request','Duplicate of another request');db()->commit();$r=one('SELECT * FROM requests WHERE id=?',[$id]);ck($r['status']==='Deleted','deleted state');ck(!canView($u['daa'],$r)&&!canView($u['faculty'],$r)&&canView($u['admin'],$r),'deleted access restricted');ck(!substitutionActions($u['hod'],$r),'deleted not approvable');ck(!array_filter(requestNotificationRows($id),fn($m)=>in_array($m['status'],['queued','failed'])),'unsent stopped');ck(one('SELECT status FROM requests WHERE id=?',[$other])['status']!=='Deleted','other request preserved');ck((bool)one("SELECT * FROM history WHERE request_id=? AND action='Deleted'",[$id]),'audit retained');deny(fn()=>adminRequestAction($u['admin'],$id,'resend_request_notifications'));
$did=submitRequest($u['daa'],$p);ck(in_array('president@example.test',array_column(requestNotificationRows($did),'recipient')),'DAA applicants still route to president');ck(in_array('tshotsho.cnr@rub.edu.bt',array_column(requestNotificationRows($did),'recipient')),'DAA applicant receives own receipt at registered address');unlink($path);echo "$n admin deletion and notification checks passed.\n";
